<?php
namespace App\Http\Controllers; use App\Models\{AnalysisBatch,Finding}; use App\Services\CompanyAccess; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class DashboardController extends Controller {public function __invoke(Request $r){$ids=CompanyAccess::ids($r->user());$b=AnalysisBatch::whereIn('company_id',$ids);return ['batches'=>['total'=>(clone $b)->count(),'processing'=>(clone $b)->whereIn('status',['uploading','queued','processing','retrying','cancelling'])->count(),'failed'=>(clone $b)->where('status','failed')->count()],'documents'=>(clone $b)->sum('document_count'),'items'=>(clone $b)->sum('item_count'),'open_findings'=>Finding::whereHas('batch',fn($q)=>$q->whereIn('company_id',$ids))->whereIn('status',['open','in_review'])->selectRaw('severity,count(*) total')->groupBy('severity')->pluck('total','severity'),'recent_batches'=>(clone $b)->with('company:id,legal_name')->latest()->limit(10)->get()];}}
